import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Identify highly significant features (p < 0.001)
    sig_features = [fid for i, fid in enumerate(feats.ids) 
                   if feats.types[i] != 'clinical' or abs(feats.x[:, feats.column(fid)].mean()) > 0.5]

    # Remove near-duplicates (correlated with |r| >= 0.6)
    to_remove = set()
    for i, a in enumerate(feats.ids):
        for j, b in enumerate(feats.ids):
            if i >= j:
                continue
            try:
                corr = np.corrcoef(feats.x[:, feats.column(a)], feats.x[:, feats.column(b)])[0,1]
                if abs(corr) >= 0.6:
                    to_remove.add(b)
            except:
                continue
    sig_features = [f for f in sig_features if f not in to_remove]

    # If no features remain after filtering, return empty design
    if len(sig_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Cluster remaining features using correlation matrix
    if len(sig_features) <= 1:
        return Design(drivers=(), columns=tuple(sig_features), products=(), loadings={})

    # Create correlation matrix for selected features
    feature_indices = [feats.column(fid) for fid in sig_features if fid in feats.ids]
    if len(feature_indices) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    X = feats.x[:, feature_indices]

    # Use hierarchical clustering
    clustering = AgglomerativeClustering(n_clusters=min(3, len(sig_features)), linkage='ward')
    labels = clustering.fit_predict(X)

    # Find best cluster by correlation with outcome
    best_cluster = None
    max_corr = -1
    for i in range(max(1, len(set(labels)))):
        cluster_features = [fid for j, fid in enumerate(sig_features) if labels[j] == i]
        if len(cluster_features) >= 2:
            try:
                scores = np.mean(X[:, [feats.column(fid) for fid in cluster_features if fid in feats.ids]], axis=1)
                corr = np.corrcoef(scores, feats.y)[0,1]
                if abs(corr) > max_corr:
                    max_corr = abs(corr)
                    best_cluster = cluster_features
            except:
                continue

    if best_cluster is None or len(best_cluster) < 2:
        return Design(drivers=(), columns=tuple(sig_features[:MAX_DRIVERS]), products=(), loadings={})

    # Build weighted score from best cluster
    try:
        cluster_indices = [feats.column(fid) for fid in best_cluster if fid in feats.ids]
        if len(cluster_indices) > 0:
            weights = np.abs(np.corrcoef(X[:, cluster_indices].T, feats.y)[0,1:-1])
            if len(weights) == 0:
                weights = np.ones(len(best_cluster))
            weights /= np.sum(weights)
            loadings = dict(zip(best_cluster, weights))
        else:
            loadings = {}
    except:
        loadings = {}

    # Return design with drivers being top features by significance
    drivers = tuple([fid for fid in sig_features if fid in best_cluster][:MAX_DRIVERS])
    columns = tuple(best_cluster)
    products = tuple([(a, b) for i, a in enumerate(best_cluster) for b in best_cluster[i+1:] if a != b])

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

